                                        dialog.Option("I'll stay.", 255);
                                        dialog.Send();
                                        break;
                                    }
                                case 4:
                                    {
                                        Data data = new Data(true);
                                        data.UID = client.Entity.UID;
                                        data.ID = 160;
                                        data.dwParam = 32;
                                        data.TimeStamp2 = client.ActiveNpc;
                                        client.Send(data);
                                        break;
                                    }
                                case 3:
                                    {
                                        client.Entity.Teleport(1002, 301, 288);
                                        client.Entity.RemoveFlag((ulong)FlagsUpdate.Flags.Ride);
                                        client.MessageBox("You have been sent to Dragon City.", null, null, 0);
                                        break;
                                    }
                                case 1:
                                    {
                                        int alive = 0;
                                        foreach (Client.GameState players in Kernel.GamePool.Values)
                                            if (players.Entity.MapID == 3333 && (!players.Entity.Dead))
                                                alive++;
                                        if (DateTime.Now.Minute >= 17 && DateTime.Now.Minute <= 25)
                                        {
                                            if (alive == 1)
                                            {
                                                if (Thread.Evento15)
                                                {
                                                    _String str = new _String(true)
