                                                    //client.Player.AddTopStatus((ulong)FlagsUpdate.Flags.TopMarcial, 2, DateTime.Now.AddHours(1));                                                            
                                                    {
                                                        //client.Entity.AddTopStatus((ulong)FlagsUpdate.Flags.Top2Warrior, DateTime.Now.AddHours(1));
                                                        Revora.Kernel.SendWorldMessage(new Message("Congratulations!  " + client.Entity.Name + " won and as a prize receives " + PremioEventos.PKTorneosCps + " CPs and a Top.", System.Drawing.Color.Black, Message.Center), Server.GamePool);
                                                    }
                                                }
                                                else
                                                {
                                                    dialog.Text("Hold. This prize has already been claimed!");
                                                    dialog.Send();
                                                }
                                            }
                                            else
                                            {
                                                dialog.Text("There are still" + alive + "Live players, kill them and come back here!");
                                                dialog.Option("Alright", 255);
                                                dialog.Send();
                                            }
                                        }
                                        else
                                        {
                                            dialog.Text("Hey" + client.Entity.Name + "You can only claim the prize after 3 minutes");
                                            dialog.Option("Alright", 255);
                                            dialog.Send();
                                        }
                                        break;

