                    #region Mapas Cps
                    case 445532:
                        {
                            switch (npcRequest.OptionID)
                            {
                                case 0:
                                    {
                                        dialog.Text("Hello" + client.Entity.Name + "this map is only for VIP5 and VIP6 where they will have many benefits");
                                        dialog.Option("Map Cps [VIP]", 1);
                                        //dialog.Option(" Auto Cps Map [FREE] ", 2);
                                        //dialog.Option(" Auto Cps Map [VIP] ", 3);
                                        dialog.Option("Only step !.", 255);
                                        dialog.Send();
                                        break;
                                    }
                                case 3:
                                    {
                                        client.Entity.Teleport(2351, 19, 127);
                                        break;
                                    }
                                case 2:
                                    {
                                        client.Entity.Teleport(19989, 340, 355);
                                        break;
                                    }
                                case 1:
                                    if (client.Entity.VIPLevel >= 5)
                                    {
                                        client.Entity.Teleport(2351, 19, 127);
                                        break;
                                    }
                                    else
                                    {
                                        dialog.Text("Only VIP 5 and VIP 6 can enter this map!");
                                        dialog.Option("Alright", 255);
                                        break;
                                    }
                            }
                            break;
                        }
                    #endregion
                        ///////مهم جدااااا
                    #region AdminDeSlayer
                    case 2920:
                        {
                            switch (npcRequest.OptionID)
                            {
                                case 0:
                                    {
                                        dialog.Text("I keep the ledgers of Revora. I can name prices, or you may seek a steward.");
                                        // dialog.Option ("Create a new account", 1);
                                        dialog.Option("Change password", 62);
                                        dialog.Option("See prices.", 19);
                                        // dialog.Option ("VIP Levels.", 22);
                                        // dialog.Option ("Prize for being connected.", 21);
                                        dialog.Option("Step.", 255);
                                        dialog.Send();
                                        break;
                                    }
                                #region
                                case 1:
                                    dialog.Text("Welcome to the help desk. Is there anything you need next?");
                                    dialog.Option("customer registration", 100);
                                    dialog.Option("web Registry", 11);
                                    dialog.Avatar(0x5f);
                                    dialog.Send();
                                    break;

                                case 62:
                                    dialog.Text("Welcome to the help desk. Is there anything you need next?");
                                    dialog.Option("Client Change password", 200);
                                    dialog.Option("Web Change Password", 66);
                                    dialog.Avatar(0x5f);
                                    dialog.Send();
                                    break;
                                #region ChangePassword
                                case 200:
                                    {
                                        dialog.Text("Hello. I am the one who was chosen to set / change the account password .you can change your password by number or characters 14 letters.");

                                        dialog.Option("I want to change the password.", 202);
                                        dialog.Option("I want to remove the password.", 33);
                                        dialog.Option("Forget it.", 255);
                                        dialog.Send();
                                        break;
                                    }

                                #region Change password

                                case 202:
                                    {
                                        if (client.Account.Password != "")
                                        {
                                            dialog.Text("Speak the old password you keep now.");
                                            dialog.Input("Here:", 206, 14);
                                            dialog.Option("Forget it.", 255);
                                        }
                                        else
                                        {
                                            dialog.Text("You have no password set on this name.");
                                            dialog.Option("Alright.", 255);
                                        }
                                        dialog.Send();
                                        break;
                                    }
                                case 206:
                                    {
                                        if (client.Account.Password != "")
                                        {
                                            if (npcRequest.Input.Length <= 14)
                                            {
                                                if (client.Account.Password == npcRequest.Input)
                                                {
                                                    dialog.Text("Please enter the password again.");
                                                    dialog.Input("Here:", 207, 14);
                                                    dialog.Option("Forget it.", 255);
                                                }
                                                else
                                                {
                                                    dialog.Text("Wrong password. Try again?");
                                                    dialog.Input("Here:", 206, 14);
                                                    dialog.Option("Forget it.", 255);
                                                }
                                            }
                                            else
                                            {
                                                dialog.Text("That password will not hold. Try again.");
                                                dialog.Input("Here:", 206, 14);
                                                dialog.Option("Alright.", 255);
